// 1. n8n ke input se dynamic rows ka data nikalna
const rows = $input.first().json.body.rows;
// 2. Data ko n8n ke standard item format mein map karna
const output = rows.map(row => {
    return {
        json: {
            "Name": row.Name || "",
            "email": row.Email || row.email || "",
            "subject": row.Subject || row.subject || "",
            "description": row.Description || row.description || "",
            "ai_enhance": row["AI Enhance"] || "", // <-- Yeh nayi line add ki hai
            "Intent": row.email || "",
            "Labels": row.Labels || ""
        }
    };
});

// 3. Output return karna jo n8n mein separate items banayega
return output;

// User ka entered label
const userLabel = $('Code in JavaScript3').first().json.Labels;

// Get Labels node se saare labels
const labels = $input.all();

// Case-insensitive comparison
const matchedLabel = labels.find(item => {
  const labelName = item.json.name;
  return labelName?.trim().toLowerCase() === userLabel?.trim().toLowerCase();
});

// Agar label exist karta hai
if (matchedLabel) {
  return [
    {
      json: {
        exists: true,
        create: false,
        label: matchedLabel.json.name,
        labelId: matchedLabel.json.id,
        messageId: $('Send a message2').first().json.id
      }
    }
  ];
}

// Agar label exist nahi karta, to create karna hai
return [
  {
    json: {
      exists: false,
      create: true,
      label: userLabel,
      messageId: $('Send a message2').first().json.id
    }
  }
];

